+    emit: (e: PipelineEvent) => {
+      if (emitImpl) emitImpl(e);
+      emitted.push(e);
+    },
+    subscribe: (_f: EventFilter, _h: EventHandler) => () => undefined,
+    query: () => [],
+    get totalEmitted() {
+      return emitted.length;
+    },
+    get bufferSize() {
+      return emitted.length;
+    },
+  };
+  return { bus, emitted };
+}
+
+function audit(score: number, findings: readonly FitnessFinding[] = []): FitnessAudit {
+  return {
+    score,
+    dimensions: {
+      canonicalPaths: 20,
+      explicitBehavior: 15,
+      determinism: 15,
+      observability: 15,
+      configSimplicity: 10,
+      layerSeparation: 10,
+      operatorErgonomics: 10,
+      governanceIntegration: 5,
+    },
+    findings,
+    timestamp: '2026-06-01T00:00:00Z',
+    version: 'test',
+  };
+}
+
