+++ b/packages/nexus-agents/src/orchestration/wave-planner.ts
@@ -12,6 +12,14 @@ export interface ExecutionWave<T> {
   readonly tasks: readonly T[];
 }
+
+export function planExecutionWaves<T>(tasks: readonly T[], maxWaveSize: number): Array<ExecutionWave<T>> {
+  const waves: Array<ExecutionWave<T>> = [];
+  for (let start = 0; start <= tasks.length; start += maxWaveSize) {
+    waves.push({ tasks: tasks.slice(start, start + maxWaveSize) });
+  }
+  return waves;
+}

